{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Compound 2, a close analogue with an amidinophenyl group, amide linkers, and multiple carboxylates, had absolute oral bioavailability too low for oral use in humans, directly supporting a low-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "DX-9065a, a zwitterionic factor Xa inhibitor with strong basic amidino/acetimidoyl groups and a carboxylic acid, had human absolute oral bioavailability of only 2–3%, strongly supporting low F for the similarly zwitterionic amidine/carboxylate query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "In fasted humans, DX-9065 given as a conventional capsule had 3% oral bioavailability, matching the query's fasted condition and reinforcing the low-F conclusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Pentamidine, a bis-amidine aromatic compound, has poor oral bioavailability in humans; the shared strongly basic amidine functionality supports low permeability and low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Revefenacin, a large polar amide/piperidine/carbamate, had absolute oral bioavailability <3% in humans, supporting low F for a highly polar, high-TPSA query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Tolperisone has very low oral bioavailability in humans, although its mechanism is first-pass metabolism rather than the permeability limitation expected for the query; it still supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "The active metabolite S-9780/perindoprilat reached only 19±7% systemic availability in young healthy subjects after oral perindopril, just below the 20% threshold and supportive of low F, though it is prodrug-derived.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Perindoprilat reached 30±6% systemic availability in cirrhotic patients after oral perindopril, a high value that is contradictory to low F but is prodrug-derived and disease-conditioned, limiting transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Glycyl-prolyl-glycine-amide was 100% bioavailable in humans at a nanogram microdose, but this dose-limited peptide result is not representative of therapeutic oral absorption for a larger, fully ionized molecule.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Encainide had 76±17% oral bioavailability in cirrhotic patients, but it is a lipophilic basic drug without the query's amidine/carboxylate polarity, so this high-F evidence has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, fully ionized zwitterion containing an amidine and a free carboxylic acid. The most transferable experimental analogues—amidine-containing carboxylates such as DX-9065a and compound 2, plus bis-amidine pentamidine—consistently show very low human oral bioavailability (2–3% or <3%). The few high-bioavailability examples are either nanogram microdose peptide data, prodrug-derived metabolite measurements, or structurally distant lipophilic drugs, and do not outweigh the direct low-F evidence. Therefore F >= 20% is unlikely.",
  "evidence_gaps": [
    "No direct human absolute bioavailability study for the exact query molecule.",
    "No experimental permeability or active-transport data for the query.",
    "The closest low-F analogues are not identical; differences in prodrug status, dose, and formulation may affect F.",
    "No data on whether the amidine/carboxylate zwitterion is a substrate for intestinal uptake or efflux transporters."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

